        if mime_type is not None:
            return ToolExecutionResult(
                content=f"Read image file [{mime_type}]",
                details={
                    "path": str(target),
                    "mime_type": mime_type,
                    "image_base64": base64.b64encode(data).decode("ascii"),
                },
            )
        text = data.decode("utf-8", errors="replace")
